/** Actual Survival item calls; rendering, outside targeting and harvest are separate stages. */
@net.neoforged.fml.common.EventBusSubscriber(modid="vandorlabs")
final class CanopyItemHostChecks {
    private record Spawned(Vec3 position,ItemStack stack){}
    private static final java.util.List<Spawned> SPAWNED=new java.util.ArrayList<>();
    @net.neoforged.bus.api.SubscribeEvent(priority=net.neoforged.bus.api.EventPriority.LOWEST) public static void spawned(net.neoforged.neoforge.event.entity.EntityJoinLevelEvent event){if(System.getProperty("vandorlabs.transmitterPhase","").startsWith("canopy-host-item-")&&!event.getLevel().isClientSide&&event.getEntity() instanceof net.minecraft.world.entity.item.ItemEntity item)SPAWNED.add(new Spawned(item.position(),item.getItem().copy()));}
    private static int checks,profiles,fault,stages;private static String context;private static final BlockPos CLICKED=new BlockPos(8,80,8),SAVED_CLICK=new BlockPos(40,238,40),SAVED_ROOT=SAVED_CLICK.above().west().north();
    static final class FaultItem extends NativeCanopyItem {
        FaultItem(NativeCanopyBlock block){super(block,new Item.Properties());}
        @Override protected boolean stage(Level level,BlockPos pos,BlockState state){stages++;if(stages==2&&(fault==1||fault==4)||stages==3&&fault==5)return false;if(stages==2&&fault==2)throw new IllegalStateException("Injected Canopy helper write failure");return super.stage(level,pos,state);}
        @Override protected NativeCanopyEntity ownerAt(Level level,BlockPos pos){if(stages==1&&(fault==6||fault==7)||stages==2&&fault==3){level.removeBlockEntity(pos);return null;}return super.ownerAt(level,pos);}
        @Override protected NativeCanopyEntity recover(Level level,BlockPos pos,NativeCanopyBlock block,NativeCanopyPlacement.Prepared prepared,CompoundTag originalItem){if(fault==6)return null;if(fault==7)throw new IllegalStateException("Injected recovery factory failure");return super.recover(level,pos,block,prepared,originalItem);}
        @Override protected boolean restore(Level level,BlockPos pos,BlockState old){return fault!=4&&fault!=5&&fault!=6&&fault!=7&&super.restore(level,pos,old);}
    }
    private static void need(boolean value,String text){checks++;if(!value)throw new AssertionError("Canopy item "+context+" "+text);}
    private static BlockPos point(JsonArray p){return new BlockPos(p.get(0).getAsInt(),p.get(1).getAsInt(),p.get(2).getAsInt());}
    private static net.neoforged.neoforge.common.util.FakePlayer actor(ServerLevel world){var player=new net.neoforged.neoforge.common.util.FakePlayer(world,new com.mojang.authlib.GameProfile(UUID.fromString("a8a166ec-43e9-4608-a44b-9ab357d1994e"),"CanopyItems"));player.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);player.getInventory().selected=0;return player;}
    private static ItemStack held(String kind,CompoundTag tag){var stack=new ItemStack(CanopyHostChecks.block(kind),2);if(tag!=null)stack.set(DataComponents.CUSTOM_DATA,CustomData.of(tag.copy()));return stack;}
    private static InteractionResult use(ServerLevel world,net.neoforged.neoforge.common.util.FakePlayer player,BlockPos clicked,Direction facing,Direction side,ItemStack stack){player.setYRot(facing.toYRot());player.setPos(clicked.getX()+.5,clicked.getY()+1,clicked.getZ()+2);player.setItemInHand(InteractionHand.MAIN_HAND,stack);stages=0;return player.gameMode.useItemOn(player,world,stack,InteractionHand.MAIN_HAND,new BlockHitResult(new Vec3(clicked.getX()+.25,clicked.getY()+.75,clicked.getZ()+.625),side,clicked,false));}
    private static void configured(ServerLevel world,net.neoforged.neoforge.common.util.FakePlayer player)throws Exception {
        Set<BlockPos> previous=new HashSet<>();int cases=0,quarantined=0;try(var reader=Files.newBufferedReader(Path.of(System.getenv("VANDOR_CANOPY_CONFIGURED_REFERENCE")))){for(String line;(line=reader.readLine())!=null;){for(var pos:previous)world.setBlock(pos,Blocks.AIR.defaultBlockState(),18);previous.clear();world.setBlock(CLICKED,Blocks.STONE.defaultBlockState(),18);var row=JsonParser.parseString(line).getAsJsonObject();String kind=row.get("id").getAsString();int profile=row.get("profile").getAsInt();context="configured/"+kind+"/"+row.get("playerFacing")+"/"+row.get("side")+"/"+profile;BlockPos foreign=row.has("foreign")?point(row.getAsJsonArray("foreign")):null;if(foreign!=null){world.getChunkAt(foreign);world.setBlock(foreign,Blocks.STONE.defaultBlockState(),18);previous.add(foreign);}var input=row.get("input");var stack=held(kind,input==null||input.isJsonNull()?null:CanopySettingsChecks.tags(input.getAsJsonObject()));var original=stack.copy();boolean unsupported=profile==8&&NativeCanopyModels.builtin().dimensions(kind).width()*3>9;boolean expected=row.get("result").getAsString().equals("SUCCESS")&&!unsupported;var result=use(world,player,CLICKED,Direction.from3DDataValue(row.get("playerFacing").getAsInt()),Direction.from3DDataValue(row.get("side").getAsInt()),stack);need(result.consumesAction()==expected,"configured actual Survival admission="+result);need(stack.getCount()==(expected?1:2)&&ItemStack.isSameItemSameComponents(stack,original),"configured held owner/NBT");need(world.getBlockState(CLICKED).is(Blocks.STONE)&&(foreign==null||world.getBlockState(foreign).is(Blocks.STONE)),"configured foreign/support retention");if(unsupported)quarantined++;
            if(expected){var pos=point(row.getAsJsonArray("root"));previous.add(pos);var owner=NativeCanopyLifecycle.at(world,pos);need(owner!=null,"configured root");var saved=owner.saveWithoutMetadata(world.registryAccess());saved.remove("NativeCanopySchema");saved.putString("id","vandorlabs:canopy");if(profile==12){need(saved.getString("ForeignCanopyData").equals("opaque-original"),"extra retained");saved.remove("ForeignCanopyData");}need(saved.equals(CanopySettingsChecks.tags(row.getAsJsonObject("saved"))),"configured actual Source saved owner");for(var rawCell:row.getAsJsonArray("cells")){var cell=point(rawCell.getAsJsonObject().getAsJsonArray("pos"));previous.add(cell);need(NativeCanopyLifecycle.at(world,cell)!=null,"configured installed cell");}}cases++;
        }}for(var pos:previous)world.setBlock(pos,Blocks.AIR.defaultBlockState(),18);need(cases==2112&&quarantined==36,"configured coverage");System.out.println("[vandorlabs][canopy-item-host] configured="+cases+" quarantinedRoles="+quarantined);
    }
    private static final BlockPos PARTIAL_CHEST=new BlockPos(8,77,16);
    private static final BlockPos BARE_CLICK=new BlockPos(72,238,72),BARE_CHEST=BARE_CLICK.offset(0,-1,3),RICH_CLICK=new BlockPos(88,238,88),RICH_CHEST=RICH_CLICK.offset(0,-1,3);
    private static ItemStack rich(){var tag=new CompoundTag();tag.putInt("CanopyDepth",17);tag.putIntArray("OpaquePlacementChoices",new int[]{9,2,7});var stack=held("canopy",tag);stack.set(DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("Retained canopy"));stack.set(DataComponents.ENCHANTMENT_GLINT_OVERRIDE,true);return stack;}
    private static void chest(ServerLevel world,BlockPos pos,ItemStack stack){world.setBlock(pos,Blocks.CHEST.defaultBlockState(),18);((net.minecraft.world.level.block.entity.ChestBlockEntity)world.getBlockEntity(pos)).setItem(0,stack.copy());}
    private static int dropped(ServerLevel world,BlockPos pos){var bounds=new AABB(pos).inflate(4);return SPAWNED.stream().filter(item->bounds.contains(item.position())).mapToInt(item->item.stack().getCount()).sum();}
    private static void factoryFaults(ServerLevel world,net.neoforged.neoforge.common.util.FakePlayer player){context="bare root and full stack recovery";
        world.getChunkAt(BARE_CLICK);world.getChunkAt(RICH_CLICK);
        for(int mode=6;mode<=7;mode++){var click=BARE_CLICK.offset((mode-6)*4,0,0);world.setBlock(click,Blocks.STONE.defaultBlockState(),18);var stack=rich();var original=stack.copy();fault=mode;boolean threw=false;try{use(world,player,click,Direction.SOUTH,Direction.UP,stack);}catch(RuntimeException expected){threw=true;}finally{fault=0;}var root=click.above();need(threw&&stack.getCount()==2&&ItemStack.isSameItemSameComponents(stack,original),"failed root/recovery factories retain complete source");need(Block.getDrops(world.getBlockState(root),world,root,null).isEmpty(),"bare root has no default drop");var revived=(NativeCanopyEntity)world.getBlockEntity(root);need(revived!=null&&revived.inert()&&!revived.initialized(),"ordinary factory recovery stays inert");need(revived.getUpdateTag(world.registryAccess()).getBoolean(NativeCanopyEntity.UNINITIALIZED),"public update preserves uninitialized distinction without private item bytes");need(NativeCanopyItem.pick(CanopyHostChecks.block("canopy").asItem(),revived).isEmpty(),"uninitialized root has no clone owner");if(mode==6){need(player.gameMode.destroyBlock(root)&&world.isEmptyBlock(root)&&dropped(world,root)==0,"actual mine has no extra owner");need(use(world,player,click,Direction.SOUTH,Direction.UP,stack).consumesAction()&&stack.getCount()==1,"mine then retry transfers exactly one owner");world.setBlock(root,Blocks.AIR.defaultBlockState(),18);world.setBlock(root.north(),Blocks.AIR.defaultBlockState(),18);}else chest(world,BARE_CHEST,stack);}
        world.setBlock(RICH_CLICK,Blocks.STONE.defaultBlockState(),18);var stack=rich();var original=stack.copyWithCount(1);fault=4;try{use(world,player,RICH_CLICK,Direction.SOUTH,Direction.UP,stack);}finally{fault=0;}var recovered=NativeCanopyLifecycle.at(world,RICH_CLICK.above());need(stack.getCount()==1&&recovered!=null&&recovered.inert(),"one source transferred to recovery");var full=recovered.placementRecoveryItem();need(full.getCount()==1&&ItemStack.isSameItemSameComponents(full,original),"exact original full components retained");chest(world,RICH_CHEST,stack);
        var contained=rich();contained.set(DataComponents.CONTAINER,net.minecraft.world.item.component.ItemContainerContents.fromItems(java.util.List.of(new ItemStack(Items.DIAMOND,3))));var nestedOriginal=contained.copy();var click=BARE_CLICK.offset(8,0,0);world.setBlock(click,Blocks.STONE.defaultBlockState(),18);need(!use(world,player,click,Direction.SOUTH,Direction.UP,contained).consumesAction()&&stages==0&&contained.getCount()==2&&ItemStack.isSameItemSameComponents(contained,nestedOriginal),"nested physical ownership refuses intact before any staging");
    }
    private static void factoryRestart(ServerLevel world){SPAWNED.clear();context="factory ownership separate-process read";world.getChunkAt(BARE_CHEST);world.getChunkAt(RICH_CHEST);var player=actor(world);var bare=BARE_CLICK.offset(4,0,0).above();var source=((net.minecraft.world.level.block.entity.ChestBlockEntity)world.getBlockEntity(BARE_CHEST)).getItem(0);var revived=(NativeCanopyEntity)world.getBlockEntity(bare);need(source.getCount()==2&&ItemStack.isSameItemSameComponents(source,rich())&&revived!=null&&revived.inert(),"source2 plus inert bare remnant after restart");need(Block.getDrops(world.getBlockState(bare),world,bare,revived).isEmpty(),"reloaded uninitialized owner remains nondropping");need(!use(world,player,bare.below(),Direction.SOUTH,Direction.UP,source).consumesAction()&&source.getCount()==2,"ordinary retry cannot replace inert remnant");need(player.gameMode.destroyBlock(bare)&&world.isEmptyBlock(bare)&&dropped(world,bare)==0,"restart mine has zero drops");need(use(world,player,bare.below(),Direction.SOUTH,Direction.UP,source).consumesAction()&&source.getCount()==1,"restart mine and retry source1 world1");
        var root=RICH_CLICK.above();var kept=((net.minecraft.world.level.block.entity.ChestBlockEntity)world.getBlockEntity(RICH_CHEST)).getItem(0);var retained=NativeCanopyLifecycle.at(world,root);need(kept.getCount()==1&&retained!=null&&retained.inert(),"source1 plus retained owner1 after restart");var loot=Block.getDrops(world.getBlockState(root),world,root,retained);need(loot.size()==1&&loot.get(0).getCount()==1&&ItemStack.isSameItemSameComponents(loot.get(0),rich()),"exact recovered full item after restart");boolean mined=player.gameMode.destroyBlock(root);int emitted=dropped(world,root);need(mined&&emitted==1,"actual recovery mine emits exactly one item mined="+mined+" emitted="+emitted+" state="+world.getBlockState(root));System.out.println("[vandorlabs][canopy-item-host] factory restart ownership PASS checks="+checks);
    }
    static void run(ServerLevel world)throws Exception {
        var player=actor(world);Set<BlockPos> previous=new HashSet<>();for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)world.getChunkAt(CLICKED.offset(x*16,0,z*16));for(var pos:BlockPos.betweenClosed(CLICKED.offset(-12,-12,-12),CLICKED.offset(12,12,12)))world.setBlock(pos,Blocks.AIR.defaultBlockState(),18);
        try(var reader=Files.newBufferedReader(Path.of(System.getenv("VANDOR_CANOPY_PLACEMENT_REFERENCE")))){for(String line;(line=reader.readLine())!=null;){for(var pos:previous)world.setBlock(pos,Blocks.AIR.defaultBlockState(),18);previous.clear();world.setBlock(CLICKED,Blocks.STONE.defaultBlockState(),18);var row=JsonParser.parseString(line).getAsJsonObject();String kind=row.get("id").getAsString();context=kind+"/"+row.get("playerFacing")+"/"+row.get("side")+"/"+row.get("profile");var raw=row.get("input");var stack=held(kind,raw==null||raw.isJsonNull()?null:CanopySettingsChecks.tags(raw.getAsJsonObject()));var result=use(world,player,CLICKED,Direction.from3DDataValue(row.get("playerFacing").getAsInt()),Direction.from3DDataValue(row.get("side").getAsInt()),stack);boolean expected=row.get("result").getAsString().equals("SUCCESS");need(result.consumesAction()==expected,"actual Survival admission result="+result+" expectedRoot="+(row.getAsJsonObject("placed").has("root")?world.getBlockState(point(row.getAsJsonObject("placed").getAsJsonArray("root"))):"none"));need(stack.getCount()==row.get("remaining").getAsInt(),"exact single consumption");var placed=row.getAsJsonObject("placed");for(var rawCell:placed.getAsJsonArray("cells")){var cell=rawCell.getAsJsonObject();var pos=point(cell.getAsJsonArray("pos"));previous.add(pos);var owner=NativeCanopyLifecycle.at(world,pos);need(owner!=null&&owner.kind().equals(kind)&&owner.facing().get3DDataValue()==cell.get("facing").getAsInt(),"installed member");need(owner.links().anchor().equals(point(cell.getAsJsonArray("anchor"))),"configured constituent anchor");}
            if(expected){var root=NativeCanopyLifecycle.at(world,point(placed.getAsJsonArray("root")));var actual=root.saveWithoutMetadata(world.registryAccess());actual.remove("NativeCanopySchema");actual.putString("id","vandorlabs:canopy");need(actual.equals(CanopySettingsChecks.tags(placed.getAsJsonObject("saved"))),"actual Source full saved owner");}if(expected&&System.getProperty("vandorlabs.transmitterPhase","").contains("harvest")){var target=point(placed.getAsJsonArray("root"));if((profiles&1)!=0)for(var cell:previous)if(!cell.equals(target)){target=cell;break;}var loot=CanopyHarvestHostChecks.mine(world,target);need(loot.size()==1&&loot.get(0).getCount()==1,"actual all-family root/helper mining emits one owner");var wanted=new CompoundTag();NativeCanopySettings.read(CanopySettingsChecks.tags(placed.getAsJsonObject("saved"))).write(wanted);need(loot.get(0).get(DataComponents.CUSTOM_DATA).copyTag().equals(wanted),"actual all-family configured harvested choices");for(var cell:previous)need(world.getBlockState(cell).isAir(),"actual all-family constituent teardown "+cell);}need(world.getBlockState(CLICKED).is(Blocks.STONE),"support retained");profiles++;
        }}for(var pos:previous)world.setBlock(pos,Blocks.AIR.defaultBlockState(),18);need(profiles==1056,"Source item callbacks");
        configured(world,player);context="rollback faults";var block=CanopyHostChecks.block("canopy");for(int mode=1;mode<=5;mode++){for(int x=-4;x<=4;x++)for(int z=-4;z<=4;z++)world.setBlock(CLICKED.offset(x,1,z),Blocks.AIR.defaultBlockState(),18);world.setBlock(CLICKED,Blocks.STONE.defaultBlockState(),18);fault=mode;var stack=held(mode==5?"long_canopy":"canopy",null);boolean threw=false;try{use(world,player,CLICKED,Direction.SOUTH,Direction.UP,stack);}catch(RuntimeException injected){threw=true;need(mode==2,"unexpected staged exception");}finally{fault=0;}var root=CLICKED.above();if(mode==4||mode==5){var retained=NativeCanopyLifecycle.at(world,root);need(stack.getCount()==1&&retained!=null&&retained.inert()&&retained.recoverySnapshot().contains(NativeCanopyEntity.RECOVERY,Tag.TAG_COMPOUND),"rollback refusal retains exactly one inert data owner");if(mode==5)chest(world,PARTIAL_CHEST,stack);}else{need(stack.getCount()==2,"failed helper installs retain held owner mode="+mode);need(world.isEmptyBlock(root),"failed placement root rolled back mode="+mode);}if(mode==2)need(threw,"original exception diagnostics preserved");}
        factoryFaults(world,player);context="configured process restart";world.getChunkAt(SAVED_CLICK);world.setBlock(SAVED_CLICK,Blocks.STONE.defaultBlockState(),18);var tag=new CompoundTag();tag.putInt("CanopyDepth",17);var generic=new CompoundTag();generic.putInt("CanopyDepth",42);tag.put("BlockEntityTag",generic);var stack=held("front_canopy_glass",tag);need(use(world,player,SAVED_CLICK,Direction.NORTH,Direction.UP,stack).consumesAction()&&stack.getCount()==1,"configured placed saved owner");var root=NativeCanopyLifecycle.at(world,SAVED_ROOT);need(root!=null&&root.settings().data().depth==17,"canonical outer precedence");System.out.println("[vandorlabs][canopy-item-host] PASS SourceCallbacks="+profiles+" checks="+checks);
    }
    static void read(ServerLevel world){factoryRestart(world);context="item separate-process read";world.getChunkAt(SAVED_ROOT);var root=NativeCanopyLifecycle.at(world,SAVED_ROOT);need(root!=null&&root.settings().data().depth==17&&root.links().anchor().equals(SAVED_ROOT),"one configured owner after process restart");world.getChunkAt(CLICKED.above());var recovery=NativeCanopyLifecycle.at(world,CLICKED.above());need(recovery!=null&&recovery.inert()&&recovery.recoverySnapshot().contains(NativeCanopyEntity.RECOVERY,Tag.TAG_COMPOUND),"rollback-refused owner remains inert with original data after restart");world.getChunkAt(PARTIAL_CHEST);var remaining=((net.minecraft.world.level.block.entity.ChestBlockEntity)world.getBlockEntity(PARTIAL_CHEST)).getItem(0);need(remaining.getCount()==1,"partial helper fault retains remaining source item across restart");var expected=recovery.placementRecoveryItem();var helpers=new java.util.ArrayList<BlockPos>();for(var cell:NativeCanopyFootprint.cells(recovery.kind(),recovery.getBlockPos(),recovery.facing(),recovery.settings(),recovery.links())){var helper=NativeCanopyLifecycle.at(world,cell);if(helper!=null&&recovery.getBlockPos().equals(helper.links().anchor()))helpers.add(cell);}need(helpers.size()==1,"partial helper fault has exactly one owned helper before mine");int before=dropped(world,recovery.getBlockPos());var player=actor(world);player.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);need(player.gameMode.destroyBlock(recovery.getBlockPos())&&dropped(world,recovery.getBlockPos())-before==1,"partial recovery mine emits one original item");for(var cell:helpers)need(world.getBlockState(cell).isAir()&&NativeCanopyLifecycle.at(world,cell)==null,"partial owned helper cannot become another drop owner");need(expected.getCount()==1&&remaining.getCount()==1,"partial recovery total source1 plus drop1");System.out.println("[vandorlabs][canopy-item-host] partial helper recovery mine PASS checks="+checks);}
}
